// HMAC-Signatur prüfen — Header x-taxtronik-signature gegen body verifizieren
import crypto from 'crypto';
const secret = $env.N8N_HMAC_SECRET;
const body = $input.item.json.body || JSON.stringify($input.item.json);
const sig = $input.item.json.headers?.['x-taxtronik-signature'] || '';
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(typeof body === 'string' ? body : JSON.stringify(body)).digest('hex');
if (sig !== expected) {
  throw new Error('HMAC-Signatur ungültig');
}
return $input.item;

